 15	type RelationTypeDropdownProps = {
 16	  arrowId: TLShapeId;
 17	  plugin: DiscourseGraphPlugin;
 18	  onSelect: (relationTypeId: string) => void;
 19	  onDismiss: () => void;
 20	};
 21	
 22	export const RelationTypeDropdown = ({
 23	  arrowId,
 24	  plugin,
 25	  onSelect,
 26	  onDismiss,
 27	}: RelationTypeDropdownProps) => {
 28	  const editor = useEditor();
 29	  const dropdownRef = useRef<HTMLDivElement>(null);
 30	  const [isAddMenuOpen, setIsAddMenuOpen] = useState(false);
 31	
 32	  const arrow = useValue<DiscourseRelationShape | null>(
 33	    "dropdownArrow",
 34	    () => editor.getShape<DiscourseRelationShape>(arrowId) ?? null,
 35	    [editor, arrowId],
 36	  );
 37	
 38	  // Auto-dismiss if arrow is deleted
 39	  useEffect(() => {
 40	    if (!arrow) {
 41	      onDismiss();
 42	    }
 43	  }, [arrow, onDismiss]);
 44	
 45	  // Get valid relation types based on source/target node types
 46	  const validRelationTypes = useMemo(() => {
 47	    if (!arrow) return [];
 48	
 49	    const bindings = getArrowBindings(editor, arrow);
 50	    if (!bindings.start || !bindings.end) return [];
 51	
 52	    const startNode = editor.getShape(bindings.start.toId);
 53	    const endNode = editor.getShape(bindings.end.toId);
 54	
 55	    if (!startNode || !endNode) return [];
 56	
 57	    const startNodeTypeId = getDiscourseNodeTypeId(startNode);
 58	    const endNodeTypeId = getDiscourseNodeTypeId(endNode);
 59	
 60	    if (!startNodeTypeId || !endNodeTypeId) return [];
 61	
 62	    return getValidRelationTypesForNodePair({
 63	      settings: plugin.settings,
 64	      sourceNodeTypeId: startNodeTypeId,
 65	      targetNodeTypeId: endNodeTypeId,
 66	    });
 67	  }, [arrow, editor, plugin]);
 68	
 69	  // Position dropdown at arrow midpoint
 70	  const dropdownPosition = useValue<{ left: number; top: number } | null>(
 71	    "dropdownPosition",
 72	    () => {
 73	      if (!arrow) return null;
 74	
 75	      const info = getArrowInfo(editor, arrow);
 76	      if (!info) return null;
 77	
 78	      // Get the midpoint in page space
 79	      const pageTransform = editor.getShapePageTransform(arrow.id);
 80	      const midInPage = pageTransform.applyToPoint(info.middle);
 81	
 82	      const vp = editor.pageToViewport(midInPage);
 83	      return { left: vp.x, top: vp.y };
 84	    },
 85	    [editor, arrow?.id],
 86	  );
 87	
 88	  // Handle click outside
 89	  useEffect(() => {
 90	    const handlePointerDown = (e: PointerEvent) => {
 91	      if (
 92	        dropdownRef.current &&
 93	        !dropdownRef.current.contains(e.target as Node)
 94	      ) {
 95	        onDismiss();
 96	      }
 97	    };
 98	
 99	    // Delay to avoid immediately triggering from the pointer up that opened this
100	    const timer = setTimeout(() => {
101	      window.addEventListener("pointerdown", handlePointerDown, true);
102	    }, 100);
103	
104	    return () => {
105	      clearTimeout(timer);
106	      window.removeEventListener("pointerdown", handlePointerDown, true);
107	    };
108	  }, [onDismiss]);
109	
110	  // Handle Escape key: close the add menu first, then the dropdown
111	  useEffect(() => {
112	    const handleKeyDown = (e: KeyboardEvent) => {
113	      if (e.key !== "Escape") return;
114	      if (isAddMenuOpen) {
115	        e.stopPropagation();
116	        setIsAddMenuOpen(false);
117	        return;
118	      }
119	      onDismiss();
120	    };
121	    window.addEventListener("keydown", handleKeyDown, true);
122	    return () => window.removeEventListener("keydown", handleKeyDown, true);
123	  }, [isAddMenuOpen, onDismiss]);
124	
125	  const handleSelect = useCallback(
126	    (relationTypeId: string) => {
127	      onSelect(relationTypeId);
128	    },
129	    [onSelect],
130	  );
131	
132	  if (!dropdownPosition || !arrow) return null;
133	
134	  const actionClassName =
135	    "flex w-full cursor-pointer items-center justify-start rounded border-none bg-transparent px-2 py-1.5 text-left text-sm font-medium text-gray-700 hover:bg-gray-100";
136	  const addActions = (
137	    <>
138	      <button className={actionClassName}>Add existing…</button>
139	      <button className={actionClassName}>Create new</button>
140	    </>
141	  );
142	  const hasRelationTypes = validRelationTypes.length > 0;
143	
144	  return (
145	    <div
146	      ref={dropdownRef}
147	      className="pointer-events-auto absolute z-30 -translate-x-1/2 -translate-y-1/2"
148	      style={{
149	        left: `${dropdownPosition.left}px`,
150	        top: `${dropdownPosition.top}px`,
151	      }}
152	      onPointerDown={(e) => e.stopPropagation()}
153	      onPointerUp={(e) => e.stopPropagation()}
154	      onClick={(e) => e.stopPropagation()}
155	    >
156	      <div className="max-h-60 min-w-40 overflow-y-auto rounded-lg border bg-white p-1 shadow-lg">
157	        <div className="flex items-center justify-between px-2 py-1">
158	          <span className="text-xs font-medium uppercase tracking-wide text-gray-500">
159	            Relation type
160	          </span>
161	          {hasRelationTypes && (
162	            <button
163	              aria-label="Add relation type"
164	              aria-expanded={isAddMenuOpen}
165	              onClick={() => setIsAddMenuOpen((open) => !open)}
166	              className="flex h-auto cursor-pointer items-center rounded border-none bg-transparent p-0.5 text-gray-500 hover:bg-gray-100"
167	              ref={(el) => (el && setIcon(el, "plus")) || undefined}
168	            />
169	          )}
170	        </div>
171	        {hasRelationTypes
172	          ? validRelationTypes.map((rt) => (
173	              <button
174	                key={rt.id}
175	                onClick={() => handleSelect(rt.id)}
176	                className="flex w-full cursor-pointer items-center gap-2 rounded border-none bg-transparent px-2 py-1.5 text-left text-sm text-gray-700 hover:bg-gray-100"
177	              >
178	                <span
179	                  className="h-2 w-2 shrink-0 rounded-full"
180	                  style={{ backgroundColor: rt.color }}
181	                />
182	                {rt.label}
183	              </button>
184	            ))
185	          : addActions}
186	      </div>
187	      {/* Outside the scroll container so it isn't clipped, inside dropdownRef so clicks don't dismiss */}
188	      {hasRelationTypes && isAddMenuOpen && (
189	        <div className="absolute left-full top-0 ml-1 min-w-32 rounded-lg border bg-white p-1 shadow-lg">
190	          {addActions}
191	        </div>
192	      )}
193	    </div>
194	  );
195	};
