 10	/**
 11	 * Finds the discourse node shape at a given page point, excluding an optional
 12	 * shape by ID (e.g. the source node or the relation arrow itself).
 13	 */
 14	export const getDiscourseNodeAtPoint = (
 15	  editor: Editor,
 16	  point: VecLike,
 17	  excludeShapeId?: TLShapeId,
 18	): TLShape | undefined => {
 19	  return editor.getShapeAtPoint(point, {
 20	    hitInside: true,
 21	    hitFrameInside: true,
 22	    margin: 0,
 23	    filter: (targetShape) =>
 24	      targetShape.type === "discourse-node" &&
 25	      !targetShape.isLocked &&
 26	      targetShape.id !== excludeShapeId,
 27	  });
 28	};
