 39	type RelationTypeSettings = {
 40	  discourseRelations: DiscourseRelation[];
 41	  relationTypes: DiscourseRelationType[];
 42	};
 43	
 44	/**
 45	 * Checks the direction of a discourse relation between two node types.
 46	 * Returns whether the relation exists in the direct (source→target)
 47	 * and/or reverse (target→source) direction.
 48	 */
 49	export const getRelationDirection = ({
 50	  discourseRelations,
 51	  relationTypeId,
 52	  sourceNodeTypeId,
 53	  targetNodeTypeId,
 54	}: {
 55	  discourseRelations: DiscourseRelation[];
 56	  relationTypeId: string;
 57	  sourceNodeTypeId: string;
 58	  targetNodeTypeId: string;
 59	}): { direct: boolean; reverse: boolean } => {
 60	  let direct = false;
 61	  let reverse = false;
 62	
 63	  for (const relation of discourseRelations) {
 64	    if (relation.relationshipTypeId !== relationTypeId) continue;
 65	    if (
 66	      relation.sourceId === sourceNodeTypeId &&
 67	      relation.destinationId === targetNodeTypeId
 68	    ) {
 69	      direct = true;
 70	    }
 71	    if (
 72	      relation.sourceId === targetNodeTypeId &&
 73	      relation.destinationId === sourceNodeTypeId
 74	    ) {
 75	      reverse = true;
 76	    }
 77	    if (direct && reverse) break;
 78	  }
 79	
 80	  return { direct, reverse };
 81	};
 82	
 83	export const getRelationLabelForDirection = ({
 84	  discourseRelations,
 85	  relationType,
 86	  sourceNodeTypeId,
 87	  targetNodeTypeId,
 88	}: {
 89	  discourseRelations: DiscourseRelation[];
 90	  relationType: DiscourseRelationType;
 91	  sourceNodeTypeId: string;
 92	  targetNodeTypeId: string;
 93	}): string => {
 94	  const { direct, reverse } = getRelationDirection({
 95	    discourseRelations,
 96	    relationTypeId: relationType.id,
 97	    sourceNodeTypeId,
 98	    targetNodeTypeId,
 99	  });
100	
101	  if (reverse && !direct) {
102	    return relationType.complement;
103	  }
104	
105	  return relationType.label;
106	};
