108	/**
109	 * Returns the list of valid relation types for a given pair of node types,
110	 * checking both directions of the discourse relations.
111	 */
112	export const getValidRelationTypesForNodePair = ({
113	  settings,
114	  sourceNodeTypeId,
115	  targetNodeTypeId,
116	}: {
117	  settings: RelationTypeSettings;
118	  sourceNodeTypeId: string;
119	  targetNodeTypeId: string;
120	}): { id: string; label: string; color: string }[] => {
121	  const validTypes: { id: string; label: string; color: string }[] = [];
122	
123	  for (const relationType of settings.relationTypes) {
124	    const { direct, reverse } = getRelationDirection({
125	      discourseRelations: settings.discourseRelations,
126	      relationTypeId: relationType.id,
127	      sourceNodeTypeId,
128	      targetNodeTypeId,
129	    });
130	
131	    if (direct || reverse) {
132	      validTypes.push({
133	        id: relationType.id,
134	        label: relationType.label,
135	        color: COLOR_PALETTE[relationType.color] ?? COLOR_PALETTE["black"]!,
136	      });
137	    }
138	  }
139	
140	  return validTypes;
141	};
142	
143	/**
144	 * Checks whether a specific relation type can connect the given source and
145	 * target node types (in either direction).
146	 */
147	export const isValidRelationConnection = ({
148	  discourseRelations,
149	  relationTypeId,
150	  sourceNodeTypeId,
151	  targetNodeTypeId,
152	}: {
153	  discourseRelations: DiscourseRelation[];
154	  relationTypeId: string;
155	  sourceNodeTypeId: string;
156	  targetNodeTypeId: string;
157	}): boolean => {
158	  const { direct, reverse } = getRelationDirection({
159	    discourseRelations,
160	    relationTypeId,
161	    sourceNodeTypeId,
162	    targetNodeTypeId,
163	  });
164	  return direct || reverse;
165	};
166	
167	/**
168	 * Returns the valid target node type IDs for a given relation type and source
169	 * node type, checking both forward and reverse directions.
170	 */
171	export const getCompatibleTargetNodeTypeIds = ({
172	  discourseRelations,
173	  relationTypeId,
174	  sourceNodeTypeId,
175	}: {
176	  discourseRelations: DiscourseRelation[];
177	  relationTypeId: string;
178	  sourceNodeTypeId: string;
179	}): string[] => {
180	  const targets = new Set<string>();
181	  for (const relation of discourseRelations) {
182	    if (relation.relationshipTypeId !== relationTypeId) continue;
183	    if (relation.sourceId === sourceNodeTypeId)
184	      targets.add(relation.destinationId);
185	    if (relation.destinationId === sourceNodeTypeId)
186	      targets.add(relation.sourceId);
187	  }
188	  return [...targets];
189	};
