import { describe, expect, it, vi } from "vitest";
import {
  associateRelationTypeWithNodePair,
  getAssociableRelationTypesForNodePair,
  getValidRelationTypesForNodePair,
} from "~/components/canvas/utils/relationTypeUtils";
import type { DiscourseRelation, DiscourseRelationType } from "~/types";

const type = (id: string, extra: Partial<DiscourseRelationType> = {}): DiscourseRelationType => ({
  id, label: id, complement: `${id}-c`, color: "black", created: 0, modified: 0, ...extra,
});
const rel = (relationshipTypeId: string, sourceId: string, destinationId: string, extra: Partial<DiscourseRelation> = {}): DiscourseRelation => ({
  id: `${relationshipTypeId}-${sourceId}-${destinationId}`, relationshipTypeId, sourceId, destinationId, created: 0, modified: 0, ...extra,
});

describe("getAssociableRelationTypesForNodePair", () => {
  const relationTypes = [
    type("supports"), type("opposes"), type("informs"),
    type("provisional", { importedFromRid: "rid:x", status: "provisional" }),
    type("importedAccepted", { importedFromRid: "rid:y", status: "accepted" }),
  ];
  const discourseRelations = [
    rel("supports", "evd", "clm"),
    rel("opposes", "clm", "evd"), // reverse direction only
    rel("informs", "evd", "qst"), // other pair
  ];
  const ids = (s: string, t: string) =>
    getAssociableRelationTypesForNodePair({ settings: { relationTypes, discourseRelations }, sourceNodeTypeId: s, targetNodeTypeId: t }).map((r) => r.id);

  it("excludes types valid in either direction and non-accepted types", () => {
    expect(ids("evd", "clm")).toEqual(["informs", "importedAccepted"]);
  });
  it("is the complement of the main menu among accepted types", () => {
    const valid = getValidRelationTypesForNodePair({ settings: { relationTypes, discourseRelations }, sourceNodeTypeId: "evd", targetNodeTypeId: "clm" }).map((r) => r.id);
    expect(valid.filter((v) => ids("evd", "clm").includes(v))).toEqual([]);
  });
  it("excludes a type already valid via a provisional triple", () => {
    const withProv = [...discourseRelations, rel("informs", "clm", "evd", { importedFromRid: "rid:z", status: "provisional" })];
    expect(getAssociableRelationTypesForNodePair({ settings: { relationTypes, discourseRelations: withProv }, sourceNodeTypeId: "evd", targetNodeTypeId: "clm" }).map((r) => r.id)).toEqual(["importedAccepted"]);
  });
  it("returns everything accepted for an empty pair", () => {
    expect(ids("qst", "clm")).toEqual(["supports", "opposes", "informs", "importedAccepted"]);
  });
});

describe("associateRelationTypeWithNodePair", () => {
  const makePlugin = (saveSettings: () => Promise<void>) => {
    const existing = [rel("supports", "evd", "clm")];
    return { existing, plugin: { settings: { discourseRelations: existing }, saveSettings: vi.fn(saveSettings) } };
  };

  it("appends a local source→target triple as a new array and saves once", async () => {
    const { existing, plugin } = makePlugin(async () => {});
    const created = await associateRelationTypeWithNodePair({ plugin: plugin as never, relationTypeId: "informs", sourceNodeTypeId: "qst", targetNodeTypeId: "clm" });
    expect(created).toMatchObject({ sourceId: "qst", destinationId: "clm", relationshipTypeId: "informs" });
    expect(created.id).toMatch(/^rel3_/);
    expect(created.created).toBe(created.modified);
    expect("status" in created || "importedFromRid" in created).toBe(false);
    expect(plugin.settings.discourseRelations).not.toBe(existing);
    expect(plugin.settings.discourseRelations).toEqual([...existing, created]);
    expect(plugin.saveSettings).toHaveBeenCalledTimes(1);
  });

  it("restores the previous array and rethrows when the save fails", async () => {
    const { existing, plugin } = makePlugin(async () => { throw new Error("disk"); });
    await expect(associateRelationTypeWithNodePair({ plugin: plugin as never, relationTypeId: "informs", sourceNodeTypeId: "qst", targetNodeTypeId: "clm" })).rejects.toThrow("disk");
    expect(plugin.settings.discourseRelations).toBe(existing);
  });

  it("saves the new triple (settings contain it at save time)", async () => {
    let seen: DiscourseRelation[] = [];
    const { plugin } = makePlugin(async () => { seen = plugin.settings.discourseRelations; });
    await associateRelationTypeWithNodePair({ plugin: plugin as never, relationTypeId: "informs", sourceNodeTypeId: "qst", targetNodeTypeId: "clm" });
    expect(seen).toHaveLength(2);
  });
});
