// ENG-2257 "Add existing…" picker, driven with real CDP mouse/key input on the ENG-2256 fixture canvas.
import { prepare, dragRelation, clickButton } from "./base2256.mjs";

const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const RIGHT = { x: -150, y: 150, z: 0.8 };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const P = (ctx) => `app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}]`;

const view = (ctx) =>
  ctx.client.evaluate(`
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".z-30");
    const menu = root?.children[0];
    const ed = window.__dgEd;
    const a = ed.getCurrentPageShapes().find((s) => s.type === "discourse-relation");
    return {
      open: !!root,
      back: !!root?.querySelector('[aria-label="Back to relation types"] svg'),
      plus: !!root?.querySelector('[aria-label="Add relation type"]'),
      flyout: !!root?.children[1],
      rows: menu ? [...menu.querySelectorAll(":scope > button")].map((b) => b.textContent.trim()) : [],
      empty: menu?.querySelector(":scope > p")?.textContent.trim() ?? null,
      arrow: a ? { relationTypeId: a.props.relationTypeId, text: a.props.text } : null,
      toasts: window.__dgToasts ?? [],
    };`);

const pair = (ctx, from, to) =>
  ctx.client.evaluate(`const ed = window.__dgEd; return { s: ed.getShape(${ctx.json(from)}).props.nodeTypeId, t: ed.getShape(${ctx.json(to)}).props.nodeTypeId };`);

// Accepted types not valid for s–t in either direction, computed independently from settings.
const expectedPickable = (ctx, { s, t }) =>
  ctx.client.evaluate(`
    const st = ${P(ctx)}.settings;
    const linked = (id) => st.discourseRelations.some((r) => r.relationshipTypeId === id &&
      ((r.sourceId === ${ctx.json(s)} && r.destinationId === ${ctx.json(t)}) || (r.sourceId === ${ctx.json(t)} && r.destinationId === ${ctx.json(s)})));
    return st.relationTypes.filter((rt) => (!rt.importedFromRid || rt.status === "accepted") && !linked(rt.id)).map((rt) => rt.label + " / " + rt.complement);`);

const snapshot = async (ctx) => ({
  relationsJson: await ctx.client.evaluate(`return app.vault.read(app.vault.getAbstractFileByPath("relations.json"));`),
  discourseRelations: await ctx.client.evaluate(`return JSON.stringify(${P(ctx)}.settings.discourseRelations);`),
});
const restore = async (ctx, state) => {
  await ctx.client.evaluate(`const ed = window.__dgEd; ed?.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id)); return true;`);
  if (!state) return;
  await ctx.client.evaluate(`const p = ${P(ctx)}; p.settings.discourseRelations = JSON.parse(${ctx.json(state.discourseRelations)}); return p.saveSettings().then(() => true);`);
  await ctx.client.evaluate(`return app.vault.modify(app.vault.getAbstractFileByPath("relations.json"), ${ctx.json(state.relationsJson)}).then(() => true);`);
};

export default [
  {
    name: "Empty pair: Add existing → pick → type listed, toast, saved",
    input: "drag Question → Claim (no types); click Add existing…; click the first picker row",
    expected: "picker lists every accepted type as 'label / complement' with a back button; after the pick the menu shows that type, 'Discourse relation added' toast, data.json has a Question→Claim triple",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      const ids = await pair(ctx, Q, C);
      await clickButton(ctx, "Add existing…", "menu");
      const picker = await view(ctx);
      const expected = await expectedPickable(ctx, ids);
      const choice = picker.rows[0];
      await clickButton(ctx, choice, "menu");
      await sleep(600);
      const after = await view(ctx);
      const disk = await ctx.client.evaluate(`return app.vault.adapter.read(${ctx.json(ctx.vault.pluginDir.replace(ctx.vault.root + "/", "") + "/data.json")}).then((t) => JSON.parse(t).discourseRelations);`);
      const label = choice?.split(" / ")[0];
      const triple = disk.filter((r) => r.sourceId === ids.s && r.destinationId === ids.t);
      return { picker, expected, choice, label, after, triple, ids };
    },
    expect: (o) => ({
      pass: o.picker.open && o.picker.back && !o.picker.plus && JSON.stringify(o.picker.rows) === JSON.stringify(o.expected) &&
        o.after.open && JSON.stringify(o.after.rows) === JSON.stringify([o.label]) && o.after.plus && !o.after.back &&
        o.after.toasts.some((t) => t.startsWith(`${o.label} relation added for `)) &&
        o.triple.length === 1 && o.triple[0].id.startsWith("rel3_") && !("status" in o.triple[0]) && !!o.after.arrow && !o.after.arrow.relationTypeId,
      actual: `picker rows=[${o.picker.rows.join(", ")}] back=${o.picker.back} plus=${o.picker.plus}; expected=[${o.expected.join(", ")}]; after rows=[${o.after.rows}] plus=${o.after.plus} toasts=[${o.after.toasts}] disk triples=${JSON.stringify(o.triple.map((r) => ({ id: r.id, s: r.sourceId, d: r.destinationId, t: r.relationshipTypeId, status: r.status })))} arrowStillPending=${!o.after.arrow?.relationTypeId}`,
    }),
    teardown: restore,
  },
  {
    name: "Empty pair: picked type then creates the relation",
    input: "Question → Claim; Add existing…; pick first row; click the new type in the menu",
    expected: "arrow gets that relationTypeId and its label as text; menu closes",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      await clickButton(ctx, "Add existing…", "menu");
      const choice = (await view(ctx)).rows[0];
      await clickButton(ctx, choice, "menu");
      await sleep(600);
      const label = choice.split(" / ")[0];
      await clickButton(ctx, label, "menu");
      await sleep(800);
      const typeId = await ctx.client.evaluate(`return ${P(ctx)}.settings.relationTypes.find((rt) => rt.label === ${ctx.json(label)})?.id;`);
      return { label, typeId, ...(await view(ctx)) };
    },
    expect: (o) => ({
      pass: !o.open && o.arrow?.relationTypeId === o.typeId && o.arrow?.text === o.label,
      actual: `menu=${o.open} arrow type=${o.arrow?.relationTypeId} (want ${o.typeId}) text="${o.arrow?.text}" (want "${o.label}")`,
    }),
    teardown: restore,
  },
