      actual: `list=[${o.list.rows}] picker=[${o.picker.rows.join(", ")}] expected=[${o.expected.join(", ")}] flyout=${o.picker.flyout}`,
    }),
    teardown: restore,
  },
  {
    name: "Escape and back chevron return to the list",
    input: "Evidence → Claim; + → Add existing…; Escape; + → Add existing…; click back chevron",
    expected: "each returns to the relation list with + visible; menu and pending arrow kept",
    run: async (ctx) => {
      await prepare(ctx, RIGHT);
      await dragRelation(ctx, E, C);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Add existing…", "flyout");
      await ctx.client.pressEscape();
      await sleep(300);
      const esc = await view(ctx);
      await clickButton(ctx, "+");
      await clickButton(ctx, "Add existing…", "flyout");
      const p = await ctx.client.evaluate(`const r = document.querySelector('[aria-label="Back to relation types"]').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
      await ctx.client.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: p.x, y: p.y, button: "none" });
      await ctx.client.send("Input.dispatchMouseEvent", { type: "mousePressed", x: p.x, y: p.y, button: "left", buttons: 1, clickCount: 1 });
      await ctx.client.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: p.x, y: p.y, button: "left", clickCount: 1 });
      await sleep(300);
      return { esc, back: await view(ctx) };
    },
    expect: ({ esc, back }) => ({
      pass: [esc, back].every((v) => v.open && v.plus && !v.back && !!v.arrow && v.rows.includes("supports")),
      actual: `after Esc open=${esc.open} rows=[${esc.rows}] plus=${esc.plus}; after chevron open=${back.open} rows=[${back.rows}] plus=${back.plus} arrow=${!!back.arrow}`,
    }),
